const [meta, google, ga4] = [$('Fetch Meta Ads Insights').all(), $('Fetch Google Ads Report').all(), $('Fetch GA4 Conversions').all()];
const metaSpend = (meta[0]?.json?.data || []).reduce((s, r) => s + Number(r.spend || 0), 0);
const googleSpend = (google[0]?.json?.results || []).reduce((s, r) => s + Number(r.metrics?.costMicros || 0) / 1e6, 0);
const totalSpend = metaSpend + googleSpend;
const conversions = (ga4[0]?.json?.rows || []).reduce((s, r) => s + Number(r.metricValues?.[0]?.value || 0), 0);
const revenue = (ga4[0]?.json?.rows || []).reduce((s, r) => s + Number(r.metricValues?.[1]?.value || 0), 0);
const roas = totalSpend > 0 ? (revenue / totalSpend) : 0;
return [{ json: { metaSpend, googleSpend, totalSpend, conversions, revenue, roas: Number(roas.toFixed(2)) } }];
